use std::io::Write;
use std::path::PathBuf;
use std::process::{Command,Output,Stdio};
use std::sync::atomic::{AtomicU64,Ordering};
const BIN:&str=env!("CARGO_BIN_EXE_lfz");
static NEXT:AtomicU64=AtomicU64::new(0);
struct Work(PathBuf);
impl Work {
 fn new()->Self {let p=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("Temp/T16-B-tooling/tests").join(format!("{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}
 fn file(&self,name:&str,body:&str)->String {let p=self.0.join(name);std::fs::write(&p,format!("#42\n{body}")).unwrap();p.to_str().unwrap().into()}
 fn run(&self,args:&[&str],stdin:&[u8])->Output {let mut c=Command::new(BIN).args(args).current_dir(&self.0).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();if let Some(mut p)=c.stdin.take(){let _=p.write_all(stdin);}let end=std::time::Instant::now()+std::time::Duration::from_secs(10);while c.try_wait().unwrap().is_none(){if std::time::Instant::now()>=end{let _=c.kill();let _=c.wait();panic!("模块check进程超时");}std::thread::sleep(std::time::Duration::from_millis(5));}c.wait_with_output().unwrap()}
}


fn success(r:Output){assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,b"{\"ok\":true}\n");assert!(r.stderr.is_empty());}
fn limit(r:Output,message:&str){assert_eq!(r.status.code(),Some(2),"{:?}",r);assert!(r.stderr.is_empty());let s=String::from_utf8(r.stdout).unwrap();assert!(s.contains("\"error\":\"ExecutionLimitError\""),"{s}");assert!(s.contains(message),"{s}");assert_eq!(s.lines().count(),1);}
#[test]fn exact_step_boundaries_zero_and_max(){let w=Work::new();for n in ["0","1"]{limit(w.run(&["-e","1","--max-steps",n,"--json"],b""),"执行步数预算已耗尽");}for n in ["2","0002","18446744073709551615"]{success(w.run(&["-e","1","--max-steps",n,"--json"],b""));}success(w.run(&["-e","let x=1\nx","--max-steps","4","--json"],b""));limit(w.run(&["-e","let x=1\nx","--max-steps","3","--json"],b""),"执行步数预算已耗尽");success(w.run(&["-e","","--max-steps","0","--timeout-ms","0","--json"],b""));}
#[test]fn positions_and_all_execution_sources(){let w=Work::new();let p=w.file("root.lfz","1\n");for args in [vec!["--max-steps","2","run",p.as_str(),"--json"],vec![p.as_str(),"--max-steps","2","--json"],vec!["run","--timeout-ms","1000","-e","1","--max-steps","2","--json"],vec!["--json","--max-steps","2","-e","1"]]{success(w.run(&args,b""));}success(w.run(&["-","--max-steps","2","--json"],b"1"));success(w.run(&["run","-","--max-steps","2","--json"],b"1"));}
#[test]fn code_and_argv_are_protected(){let w=Work::new();for code in ["--max-steps","--timeout-ms","--max-steps=1"]{let r=w.run(&["check","-e",code,"--json"],b"");let s=String::from_utf8(r.stdout).unwrap();assert!(s.contains("\"mode\":\"check\""),"{s}");}let r=w.run(&["--max-steps","1000","-e","print(join(\",\",argv()))","--","--max-steps","9","--timeout-ms=2"],b"");assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,b"--max-steps,9,--timeout-ms=2\n");}
#[test]fn strict_values_duplicates_and_missing(){let w=Work::new();for flag in ["--max-steps","--timeout-ms"]{for value in ["","+1","-1"," 1","1 ","1_0","1.0","１２","18446744073709551616"]{let r=w.run(&[flag,value,"-e","","--json"],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains(&format!("选项 '{flag}' 的值必须是非负十进制 u64")));}for args in [vec![flag],vec!["-e","",flag,"--"]]{let r=w.run(&args,b"");assert!(String::from_utf8_lossy(&r.stderr).contains("需要一个非负十进制 u64 参数"));}let r=w.run(&[flag,"0",flag,"1","-e",""],b"");assert!(String::from_utf8_lossy(&r.stderr).contains("不能重复"));}}
#[test]fn non_execution_commands_reject_limits_before_loading(){let w=Work::new();for cmd in ["check","test","--help","--version"]{let r=w.run(&[cmd,"--max-steps","0"],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("执行限额选项只适用于运行命令"),"{:?}",r);let r=w.run(&[cmd,"--timeout-ms","bad"],b"");assert!(String::from_utf8_lossy(&r.stderr).contains("的值必须是非负十进制 u64"));}for x in ["--max-steps=1","--timeout-ms=1"]{let r=w.run(&["--help",x],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());let flag=x.split('=').next().unwrap();assert!(String::from_utf8_lossy(&r.stderr).contains(&format!("选项 '{flag}' 不支持等号写法，请使用 '{flag} N'")));}}
#[test]fn zero_timeout_and_frontend_priority(){let w=Work::new();limit(w.run(&["-e","1","--timeout-ms","0","--json"],b""),"执行时间上限已到");let r=w.run(&["-e","let =","--timeout-ms","0","--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("SyntaxError"));let r=w.run(&["run","missing.lfz","--timeout-ms","0","--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("IOError"));}
#[test]fn attempt_cannot_swallow_and_prior_side_effect_remains(){let w=Work::new();let r=w.run(&["-e","print(1)\nattempt(()=>{while true {}})","--max-steps","30","--json"],b"");assert_eq!(r.status.code(),Some(2));assert_eq!(r.stderr,b"1\n");assert!(String::from_utf8_lossy(&r.stdout).contains("ExecutionLimitError"));}
#[test]fn graph_budget_failure_keeps_dependency_origin(){let w=Work::new();w.file("dep.lfz","while true {}\n");let p=w.file("root.lfz","import d from \"./dep.lfz\"\nprint(99)\n");let r=w.run(&["run",&p,"--max-steps","20","--json"],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stderr.is_empty());let s=String::from_utf8(r.stdout).unwrap();assert!(s.contains("ExecutionLimitError"));assert!(s.contains("dep.lfz"));assert!(!s.contains("root.lfz"));}
#[test]fn timeout_duration_platform_overflow_is_usage_not_host_failure(){let w=Work::new();let r=w.run(&["-e","","--timeout-ms","18446744073709551615","--json"],b"");if std::time::Instant::now().checked_add(std::time::Duration::from_millis(u64::MAX)).is_none(){assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());let s=String::from_utf8(r.stderr).unwrap();assert!(s.contains("选项 '--timeout-ms' 超出当前平台可表示的时间范围"));assert!(!s.contains("模块执行上下文无效"));}else{success(r);}}
